<?php
/**
 * Database configuration TEMPLATE.
 *
 * This file is safe to commit to git — it contains no real credentials.
 *
 * Setup:
 *   1. Copy this file to config/database.php
 *        (config/database.php is gitignored, so your real credentials
 *        never get committed)
 *   2. Fill in your local MySQL username/password below in the copy.
 *   3. Do NOT edit this file with real credentials — edit the copy.
 */

$config = [
    'host'    => 'localhost',
    'dbname'  => 'task_manager',
    'username'=> 'root',
    'password'=> '',
    'charset' => 'utf8mb4',
];

/**
 * Returns a shared PDO instance. Using a function with a static variable
 * means every page that needs the database gets the same connection
 * without duplicating connection code.
 */
function getDB(): PDO
{
    static $pdo = null;

    if ($pdo === null) {
        global $config;

        $dsn = "mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}";

        $options = [
            // Throw exceptions on error instead of failing silently.
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            // Return associative arrays by default.
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            // Use real prepared statements (not emulated) for stronger
            // protection against SQL injection.
            PDO::ATTR_EMULATE_PREPARES   => false,
        ];

        try {
            $pdo = new PDO($dsn, $config['username'], $config['password'], $options);
        } catch (PDOException $e) {
            // Never leak connection details or stack traces to the client.
            error_log('Database connection failed: ' . $e->getMessage());
            http_response_code(500);
            die('Something went wrong. Please try again later.');
        }
    }

    return $pdo;
}
